use vstd::prelude::*;
use vstd::slice::*;
use vstd::vec::*;

verus! {

spec fn is_even(x: i32) -> bool {
    x % 2 == 0
}

spec fn contains_even(slice: &[i32], x: i32) -> bool {
    exists|i: int| 0 <= i < slice.len() && slice[i] == x && is_even(x)
}

spec fn all_even_elements_present(result: &[i32], input: &[i32]) -> bool {
    forall|i: int| 0 <= i < input.len() && is_even(input[i]) ==> 
        exists|j: int| 0 <= j < result.len() && result[j] == input[i]
}

spec fn all_result_elements_even_and_from_input(result: &[i32], input: &[i32]) -> bool {
    forall|j: int| 0 <= j < result.len() ==> 
        is_even(result[j]) && exists|i: int| 0 <= i < input.len() && input[i] == result[j]
}

fn remove_odd_numbers(arr: &[i32]) -> (result: Vec<i32>)
    ensures
        // All even elements from input appear in result
        all_even_elements_present(result.view(), arr),
        // All elements in result are even and from input
        all_result_elements_even_and_from_input(result.view(), arr),
{
    let mut result_vec = Vec::new();
    let mut idx: usize = 0;
    
    while idx < arr.len()
        invariant
            0 <= idx <= arr.len(),
            // All even elements processed so far are in result
            forall|i: int| 0 <= i < idx && is_even(arr[i]) ==> 
                exists|j: int| 0 <= j < result_vec.len() && result_vec[j] == arr[i],
            // All elements in result are even and from processed portion
            forall|j: int| 0 <= j < result_vec.len() ==> 
                is_even(result_vec[j]) && exists|i: int| 0 <= i < idx && arr[i] == result_vec[j],
        decreases arr.len() - idx,
    {
        let elem = arr[idx];
        if elem % 2 == 0 {
            result_vec.push(elem);
        }
        idx = idx + 1;
    }
    
    result_vec
}

}